CREATE TABLE IF NOT EXISTS communication_identities(user_id INTEGER PRIMARY KEY,version BIGINT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS communication_identity_outbox(user_id INTEGER NOT NULL,version BIGINT NOT NULL,payload TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at BIGINT NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',PRIMARY KEY(user_id,version));
CREATE TABLE IF NOT EXISTS communication_tickets(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,session_id TEXT NOT NULL,expires_at BIGINT NOT NULL,session_expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS communication_revoked_sessions(session_id TEXT PRIMARY KEY,expires_at BIGINT NOT NULL);
CREATE OR REPLACE FUNCTION communication_capture_identity() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE u users%ROWTYPE; p text; BEGIN IF TG_OP='DELETE' THEN u:=OLD; ELSE u:=NEW; END IF; p:=json_build_object('user_id',u.id,'nickname',COALESCE(u.display_name,u.username),'avatar_icon',COALESCE(u.avatar_icon,''),'status',CASE WHEN TG_OP='DELETE' THEN 'deleted' WHEN u.disabled=1 THEN 'disabled' ELSE 'active' END,'role',u.role,'permissions',CASE WHEN TG_OP='DELETE' THEN '[]'::json ELSE u.permissions::json END)::text; INSERT INTO communication_identities(user_id,version,payload) VALUES(u.id,1,p) ON CONFLICT(user_id) DO UPDATE SET version=communication_identities.version+1,payload=excluded.payload; INSERT INTO communication_identity_outbox(user_id,version,payload) SELECT user_id,version,payload FROM communication_identities WHERE user_id=u.id; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE OR REPLACE TRIGGER communication_user_insert AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION communication_capture_identity();
CREATE OR REPLACE TRIGGER communication_user_update AFTER UPDATE OF display_name,username,avatar_icon,disabled,role,permissions ON users FOR EACH ROW WHEN (OLD.display_name IS DISTINCT FROM NEW.display_name OR OLD.username IS DISTINCT FROM NEW.username OR OLD.avatar_icon IS DISTINCT FROM NEW.avatar_icon OR OLD.disabled IS DISTINCT FROM NEW.disabled OR OLD.role IS DISTINCT FROM NEW.role OR OLD.permissions IS DISTINCT FROM NEW.permissions) EXECUTE FUNCTION communication_capture_identity();
CREATE OR REPLACE TRIGGER communication_user_delete BEFORE DELETE ON users FOR EACH ROW EXECUTE FUNCTION communication_capture_identity();
INSERT INTO communication_identities SELECT u.id,1,json_build_object('user_id',u.id,'nickname',COALESCE(u.display_name,u.username),'avatar_icon',COALESCE(u.avatar_icon,''),'status',CASE WHEN u.disabled=1 THEN 'disabled' ELSE 'active' END,'role',u.role,'permissions',u.permissions::json)::text FROM users u ON CONFLICT DO NOTHING;
INSERT INTO communication_identity_outbox(user_id,version,payload) SELECT user_id,version,payload FROM communication_identities ON CONFLICT DO NOTHING;
UPDATE _schema_version SET version=21;
